import { describe, expect, it } from "vitest"
import { redactKnownValues, SecretCollector } from "../src/network-redaction.ts"

describe("SecretCollector", () => {
  it("preserves credential placement while deduplicating values", () => {
    const collector = new SecretCollector()
    const headers = collector.protectHeaders([
      { name: "Authorization", value: "Bearer token-value" },
      { name: "Cookie", value: "session=cookie-value; theme=dark" },
      { name: "X-CSRF-Token", value: "token-value" },
      { name: "Accept", value: "application/json" },
    ], "request")

    expect(headers).toEqual([
      { name: "Authorization", value: "Bearer ${BC_SECRET_1}" },
      { name: "Cookie", value: "session=${BC_SECRET_2}; theme=${BC_SECRET_3}" },
      { name: "X-CSRF-Token", value: "${BC_SECRET_1}" },
      { name: "Accept", value: "application/json" },
    ])
    expect(collector.slots()).toEqual([
      expect.objectContaining({ ref: "BC_SECRET_1", value: "token-value" }),
      expect.objectContaining({ ref: "BC_SECRET_2", value: "cookie-value" }),
      expect.objectContaining({ ref: "BC_SECRET_3", value: "dark" }),
    ])
  })

  it("redacts token-like URL and JSON fields", () => {
    const collector = new SecretCollector()
    const url = collector.protectUrl("https://example.com/api?access_token=abc&limit=10")
    const body = collector.protectBody(JSON.stringify({ user: "kit", nested: { refreshToken: "def" } }), "application/json", "response")

    expect(url).toBe("https://example.com/api?access_token=${BC_SECRET_1}&limit=10")
    expect(JSON.parse(body!)).toEqual({ user: "kit", nested: { refreshToken: "${BC_SECRET_2}" } })
  })

  it("redacts numeric and collection credentials in JSON", () => {
    const collector = new SecretCollector()
    const body = collector.protectBody(JSON.stringify({ otp: 123456, tokens: ["first-token", "second-token"] }), "application/json", "response")

    expect(JSON.parse(body!)).toEqual({
      otp: "${BC_SECRET_1}",
      tokens: ["${BC_SECRET_2}", "${BC_SECRET_3}"],
    })
    expect(collector.slots().map((slot) => slot.value)).toEqual(["123456", "first-token", "second-token"])
  })

  it("keeps references literal in form bodies", () => {
    const collector = new SecretCollector()
    expect(collector.protectBody("csrf_token=abc&name=kit", "application/x-www-form-urlencoded", "request"))
      .toBe("csrf_token=${BC_SECRET_1}&name=kit")
  })

  it("preserves duplicate form fields and counts empty secret occurrences", () => {
    const collector = new SecretCollector()
    expect(collector.protectBody("token=&name=one&token=first&name=two&token=second", "application/x-www-form-urlencoded", "request", "POST /api"))
      .toBe("token=&name=one&token=${BC_SECRET_1}&name=two&token=${BC_SECRET_2}")
    expect(collector.slots()).toEqual([
      { ref: "BC_SECRET_1", value: "first", sources: ["POST /api.request.form.token.1"] },
      { ref: "BC_SECRET_2", value: "second", sources: ["POST /api.request.form.token.2"] },
    ])
  })

  it("redacts multipart credential fields and preserves their placement", () => {
    const collector = new SecretCollector()
    const body = [
      "--boundary",
      'Content-Disposition: form-data; name="username"',
      "",
      "kit",
      "--boundary",
      'Content-Disposition: form-data; name="password"',
      "",
      "secret-password",
      "--boundary--",
      "",
    ].join("\r\n")
    expect(collector.protectBody(body, "multipart/form-data; boundary=boundary", "request"))
      .toBe(body.replace("secret-password", "${BC_SECRET_1}"))
    expect(collector.slots()).toEqual([
      expect.objectContaining({ ref: "BC_SECRET_1", value: "secret-password" }),
    ])
  })

  it("omits multipart bodies containing file parts", () => {
    const collector = new SecretCollector()
    const body = [
      "--boundary",
      'Content-Disposition: form-data; name="upload"; filename="secret.txt"',
      "Content-Type: text/plain",
      "",
      "opaque content",
      "--boundary--",
      "",
    ].join("\r\n")
    expect(collector.protectBody(body, "multipart/form-data; boundary=boundary", "request")).toBeUndefined()
  })

  it("updates stable refs by source during refresh", () => {
    const collector = new SecretCollector([{ ref: "BC_SECRET_4", value: "old", sources: ["request.header.authorization"] }])
    expect(collector.protectHeaders([{ name: "Authorization", value: "Bearer new" }], "request")).toEqual([
      { name: "Authorization", value: "Bearer ${BC_SECRET_4}" },
    ])
    expect(collector.slots()[0]).toMatchObject({ ref: "BC_SECRET_4", value: "new" })
    expect(collector.updatedRefs()).toEqual(["BC_SECRET_4"])
    expect(collector.observedRefs()).toEqual(["BC_SECRET_4"])
  })

  it("reports an unchanged credential as observed but not updated", () => {
    const collector = new SecretCollector([{ ref: "BC_SECRET_1", value: "same", sources: ["request.header.authorization"] }])
    collector.protectHeaders([{ name: "Authorization", value: "Bearer same" }], "request")
    expect(collector.observedRefs()).toEqual(["BC_SECRET_1"])
    expect(collector.updatedRefs()).toEqual([])
  })

  it("retains rotated values for output redaction without persisting history", () => {
    const collector = new SecretCollector([{ ref: "BC_SECRET_4", value: "old-token", sources: ["request.header.authorization"] }])
    for (const value of ["middle-token", "latest-token"]) {
      collector.protectHeaders([{ name: "Authorization", value: `Bearer ${value}` }], "request")
    }
    expect(collector.redactText("old-token middle-token latest-token ${BC_SECRET_4}"))
      .toBe("${BC_SECRET_4} ${BC_SECRET_4} ${BC_SECRET_4} ${BC_SECRET_4}")
    expect(collector.redactValue({ echoes: ["old-token", "middle-token", "latest-token"] }))
      .toEqual({ echoes: ["${BC_SECRET_4}", "${BC_SECRET_4}", "${BC_SECRET_4}"] })
    expect(collector.slots()).toEqual([{ ref: "BC_SECRET_4", value: "latest-token", sources: ["request.header.authorization"] }])
    expect(new SecretCollector(collector.slots()).redactText("old-token middle-token latest-token"))
      .toBe("old-token middle-token ${BC_SECRET_4}")
  })

  it.each(["https://example.com/callback", "/callback", "", "//example.com/callback"])("protects OAuth fragments in Location URLs: %s", (base) => {
    const collector = new SecretCollector()
    expect(collector.protectHeaders([{
      name: "Location",
      value: `${base}#access_token=first-token&id_token=second-token&access_token=third-token&label=a%20b&flag`,
    }], "response")).toEqual([{
      name: "Location",
      value: `${base}#access_token=\${BC_SECRET_1}&id_token=\${BC_SECRET_2}&access_token=\${BC_SECRET_3}&label=a%20b&flag`,
    }])
    expect(collector.slots().map((slot) => slot.sources)).toEqual([
      ["response.header.location.url.fragment.access_token"],
      ["response.header.location.url.fragment.id_token"],
      ["response.header.location.url.fragment.access_token.1"],
    ])
  })

  it("keeps query and fragment credential sources independent", () => {
    const collector = new SecretCollector()
    expect(collector.protectUrl("/callback?access_token=query-token#access_token=fragment-token"))
      .toBe("/callback?access_token=${BC_SECRET_1}#access_token=${BC_SECRET_2}")
    expect(collector.slots().map((slot) => slot.value)).toEqual(["query-token", "fragment-token"])
  })

  it.each(["#public%20anchor", "#tab=hello%20world&flag", "#/route?tab=public", "#section?access_token=public-text"])("preserves public fragments verbatim: %s", (fragment) => {
    const collector = new SecretCollector()
    expect(collector.protectUrl(`/callback${fragment}`)).toBe(`/callback${fragment}`)
    expect(collector.protectUrl(`https://example.com/callback${fragment}`)).toBe(`https://example.com/callback${fragment}`)
    expect(collector.slots()).toEqual([])
  })

  it("keeps credentials from different request sources independent", () => {
    const collector = new SecretCollector()
    const first = collector.protectHeaders([{ name: "Authorization", value: "Bearer first" }], "request", "GET https://one.example/api")
    const second = collector.protectHeaders([{ name: "Authorization", value: "Bearer second" }], "request", "GET https://two.example/api")
    expect(first[0]?.value).toBe("Bearer ${BC_SECRET_1}")
    expect(second[0]?.value).toBe("Bearer ${BC_SECRET_2}")
  })

  it("splits shared refs when one source rotates", () => {
    const collector = new SecretCollector([{
      ref: "BC_SECRET_1",
      value: "shared",
      sources: ["GET https://one.example/api.request.header.authorization", "GET https://two.example/api.request.header.authorization"],
    }])
    const protectedHeaders = collector.protectHeaders(
      [{ name: "Authorization", value: "Bearer rotated" }],
      "request",
      "GET https://one.example/api",
    )
    expect(protectedHeaders[0]?.value).toBe("Bearer ${BC_SECRET_2}")
    expect(collector.slots()).toEqual([
      expect.objectContaining({ ref: "BC_SECRET_1", value: "shared", sources: ["GET https://two.example/api.request.header.authorization"] }),
      expect.objectContaining({ ref: "BC_SECRET_2", value: "rotated", sources: ["GET https://one.example/api.request.header.authorization"] }),
    ])
  })

  it("preserves duplicate query parameters while redacting each occurrence", () => {
    const collector = new SecretCollector()
    expect(collector.protectUrl("https://example.com/api?token=first&token=second"))
      .toBe("https://example.com/api?token=${BC_SECRET_1}&token=${BC_SECRET_2}")
  })

  it("redacts token-like parameters in relative redirect URLs", () => {
    const collector = new SecretCollector()
    expect(collector.protectHeaders([{ name: "Location", value: "/callback?code=secret#done" }], "response"))
      .toEqual([{ name: "Location", value: "/callback?code=${BC_SECRET_1}#done" }])
  })

  it("preserves duplicate cookie names as independent references", () => {
    const collector = new SecretCollector()
    expect(collector.protectHeaders([{ name: "Cookie", value: "sid=first; sid=second" }], "request"))
      .toEqual([{ name: "Cookie", value: "sid=${BC_SECRET_1}; sid=${BC_SECRET_2}" }])
  })

  it("redacts 4+ char substrings while keeping 1-char values from corrupting URLs", () => {
    expect(redactKnownValues("https://example.com/v1/dark-mode?limit=10", [
      { ref: "BC_SECRET_1", value: "1" },
      { ref: "BC_SECRET_2", value: "dark" },
    ])).toBe("https://example.com/v1/${BC_SECRET_2}-mode?limit=10")
  })

  it("does not rewrite stable placeholders during exact-value output redaction", () => {
    expect(redactKnownValues("${BC_SECRET_1}", [
      { ref: "BC_SECRET_2", value: "BC_SECRET_1" },
    ])).toBe("${BC_SECRET_1}")
  })

  it("redacts exact known values from command output", () => {
    expect(redactKnownValues("using secret-value twice secret-value", [
      { ref: "BC_SECRET_1", value: "secret-value" },
    ])).toBe("using ${BC_SECRET_1} twice ${BC_SECRET_1}")
  })

  it("combines known values and secret-shaped fields without changing nested scalar semantics", () => {
    const collector = new SecretCollector([
      { ref: "BC_SECRET_1", value: "known-token", sources: ["request.header.authorization"] },
      { ref: "BC_SECRET_2", value: "42", sources: ["request.body.pin"] },
      { ref: "BC_SECRET_3", value: "false", sources: ["request.body.flag"] },
    ])
    const input = {
      label: "prefix known-token ${BC_SECRET_1}",
      items: [42, false, null, "", { password: ["unknown", 42, false, null, "", { nested: "known-token" }] }],
      credentials: { empty: "", missing: null, flag: false, nested: [{ label: "not previously observed" }] },
      untouched: { value: "plain", count: 7 },
    }
    const original = structuredClone(input)

    expect(collector.redactValue(input)).toEqual({
      label: "prefix ${BC_SECRET_1} ${BC_SECRET_1}",
      items: ["${BC_SECRET_2}", "${BC_SECRET_3}", null, "", { password: ["[REDACTED]", "[REDACTED]", "[REDACTED]", null, "", { nested: "[REDACTED]" }] }],
      credentials: { empty: "", missing: null, flag: "[REDACTED]", nested: [{ label: "[REDACTED]" }] },
      untouched: { value: "plain", count: 7 },
    })
    expect(input).toEqual(original)
  })
})

import { Effect, Match } from "effect"
import { execFile } from "node:child_process"
import fs from "node:fs/promises"
import os from "node:os"
import path from "node:path"
import { promisify } from "node:util"
import { afterEach, describe, expect, it } from "vitest"
import { prepareRuntime, selectRuntime } from "../scripts/runtime-install.ts"

const exec = promisify(execFile)
const packageName = "@opencode-ai/browser-control"
const marker = ".browser-control-runtime.json"
const temporary: string[] = []

afterEach(async () => {
  await Promise.all(temporary.splice(0).map((directory) => fs.rm(directory, { recursive: true, force: true })))
})

async function fixture(options: { readonly mcpProbe?: "startup" | "initialize" | "tools/list" | "skill" | "session_current" } = {}) {
  const directory = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), "browser-control-runtime-")))
  temporary.push(directory)
  const source = path.join(directory, "checkout")
  const staging = path.join(directory, "staging")
  const install = path.join(directory, "install")
  const active = path.join(directory, "active")
  for (const relative of ["src", "scripts", "extension/src", "extension/icons", "extension/dist", "dist", "node_modules", "skills/browser-control"]) {
    await fs.mkdir(path.join(source, relative), { recursive: true })
  }
  await fs.writeFile(path.join(source, "package.json"), JSON.stringify({
    name: packageName,
    version: "1.2.3",
    packageManager: "pnpm@11.20.0",
    type: "module",
    exports: {
      ".": "./dist/index.js",
      "./server": "./dist/opencode.js",
    },
    dependencies: { effect: "4.0.0-rc.118", "@effect/platform-node": "4.0.0-rc.118" },
  }))
  for (const relative of ["pnpm-lock.yaml", "pnpm-workspace.yaml", "tsconfig.json", "tsconfig.build.json", "extension/manifest.json", "README.md", "LICENSE"]) {
    await fs.writeFile(path.join(source, relative), "fixture")
  }
  await fs.writeFile(path.join(source, "src/untracked.ts"), "untracked source is included")
  await fs.writeFile(path.join(source, "skills/browser-control/SKILL.md"), "# Browser Control\nFixture skill\n")
  for (const relative of ["dist", "node_modules", "extension/dist"]) await fs.writeFile(path.join(source, relative, "untouched"), "live")

  // Fake only expensive build/package-manager/compiler steps. Installed binaries,
  // SDK resolution, MCP protocol, filesystem isolation and selection run for real.
  // The strict pnpm consumer runs against a real tarball in CI's runtime:prepare.
  const run = (command: string, args: string[], cwd: string, env?: NodeJS.ProcessEnv) => Effect.tryPromise(async () => {
    if (path.basename(cwd).startsWith(".browser-control-pnpm-")) {
      expect(path.dirname(cwd)).toBe(directory)
      expect(env).toEqual({
        PATH: process.env.PATH, SystemRoot: process.env.SystemRoot, HOME: cwd,
        XDG_CONFIG_HOME: path.join(cwd, "config"), XDG_DATA_HOME: path.join(cwd, "data"),
        XDG_CACHE_HOME: path.join(cwd, "cache"), XDG_STATE_HOME: path.join(cwd, "state"),
      })
      expect(await fs.readFile(path.join(cwd, "package.json"), "utf8")).toBe(JSON.stringify({ private: true, type: "module", packageManager: "pnpm@11.20.0" }))
      if (command === "pnpm") {
        expect(args).toEqual(["add", "--workspace-root", "--prod", "--ignore-scripts", "--config.node-linker=isolated", path.join(staging, "artifacts/package.tgz")])
        await expect(fs.lstat(path.join(cwd, "pnpm-lock.yaml"))).rejects.toMatchObject({ code: "ENOENT" })
      }
      return Match.value(args[0]).pipe(
        Match.when("--version", () => "browser-control v1.2.3"),
        Match.when("--help", () => "browser-control help"),
        Match.orElse(() => ""),
      )
    }
    if (command === "pnpm") {
      expect(cwd).toBe(staging)
      if (args[0] === "install") {
        expect(args).toEqual(["install", "--frozen-lockfile"])
        expect(await fs.readFile(path.join(staging, "src/untracked.ts"), "utf8")).toBe("untracked source is included")
        for (const relative of ["dist", "node_modules", "extension/dist"]) {
          await expect(fs.lstat(path.join(staging, relative))).rejects.toMatchObject({ code: "ENOENT" })
        }
      }
      return ""
    }
    if (command === "npm" && args[0] === "pack") {
      expect(args).toContain("--ignore-scripts")
      await fs.writeFile(path.join(staging, "artifacts/package.tgz"), "fake tarball")
      return "package.tgz\n"
    }
    if (command === "npm" && args[0] === "install") {
      expect(JSON.parse(await fs.readFile(path.join(install, "package.json"), "utf8")).overrides).toEqual({ effect: "4.0.0-rc.118", "@effect/platform-node-shared": "4.0.0-rc.118" })
      expect(args).toContain("--ignore-scripts")
      expect(cwd).toBe(install)
      const pkg = path.join(install, "node_modules", packageName)
      await fs.mkdir(path.join(pkg, "dist"), { recursive: true })
      await fs.copyFile(path.join(staging, "package.json"), path.join(pkg, "package.json"))
      await fs.cp(path.join(staging, "skills"), path.join(pkg, "skills"), { recursive: true })
      await fs.writeFile(path.join(pkg, "dist/index.js"), "export const BrowserControlClient = { Service: {} }; export const AuthenticatedOrigin = { reveal() {} }; export const SecretProfile = { run() {}, Error: class extends Error {} };\n")
      await fs.writeFile(path.join(pkg, "dist/opencode.js"), `
import { fileURLToPath } from 'node:url';
import fs from 'node:fs/promises';
export const mcpServerConfig = () => ({ type: 'local', command: ['node', fileURLToPath(new URL('./mcp.js', import.meta.url))] });
export const extensionDirectory = () => fileURLToPath(new URL('../extension/dist', import.meta.url));
export const skillDefinition = async () => ({ id: 'browser', location: fileURLToPath(new URL('../skills/browser-control/SKILL.md', import.meta.url)), content: await fs.readFile(new URL('../skills/browser-control/SKILL.md', import.meta.url), 'utf8') + extensionDirectory() });
export default { id: 'browser-control' };
`)
      await fs.writeFile(path.join(pkg, "dist/cli.js"), `#!/usr/bin/env node
import fs from 'node:fs';
const argument = process.argv[2];
console.log(argument === '--version' ? 'browser-control v1.2.3' : argument === 'skill' ? fs.readFileSync(new URL('../skills/browser-control/SKILL.md', import.meta.url), 'utf8').trim() : 'browser-control help');
`)
      await fs.writeFile(path.join(pkg, "dist/mcp.js"), `#!/usr/bin/env node
import fs from 'node:fs';
import readline from 'node:readline';
const probe = ${JSON.stringify(options.mcpProbe ?? null)};
const probeRelay = () => fetch('http://127.0.0.1:' + process.env.BROWSER_CONTROL_PORT + '/version');
if (probe === 'startup') await probeRelay();
for await (const line of readline.createInterface({ input: process.stdin })) {
  const request = JSON.parse(line);
  if (!request.id) continue;
  if (request.method === probe || request.params?.name === probe) await probeRelay();
  console.log(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/tools/list_changed' }));
  const result = request.method === 'initialize' ? { serverInfo: { name: 'browser-control', version: '1.2.3' } }
    : request.method === 'tools/list' ? { tools: [{ name: 'execute' }, { name: 'skill' }, { name: 'session_current' }] }
    : request.params?.name === 'session_current' ? { isError: false, structuredContent: { currentSession: process.env.BROWSER_CONTROL_SESSION } }
    : { content: [{ type: 'text', text: fs.readFileSync(new URL('../skills/browser-control/SKILL.md', import.meta.url), 'utf8') }] };
  console.log(JSON.stringify({ jsonrpc: '2.0', id: request.id, result }));
}
`)
      await fs.mkdir(path.join(install, "node_modules/.bin"))
      for (const [bin, file] of Object.entries({ "browser-control": "cli.js", "browser-control-mcp": "mcp.js" })) {
        await fs.chmod(path.join(pkg, "dist", file), 0o755)
        await fs.symlink(`../${packageName}/dist/${file}`, path.join(install, "node_modules/.bin", bin))
      }
      return ""
    }
    if (command.endsWith("/.bin/tsc")) return ""
    return (await exec(command, args, { cwd, timeout: 10_000 })).stdout
  }).pipe(Effect.mapError((cause) => new Error("Fixture command failed", { cause })))
  return { directory, source, staging, install, active, run }
}

describe("isolated runtime installation", () => {
  it.each(["startup", "initialize", "tools/list", "skill", "session_current"] as const)("rejects MCP relay requests during %s without stamping the candidate", async (mcpProbe) => {
    const f = await fixture({ mcpProbe })
    await fs.symlink(f.source, f.active)
    await expect(Effect.runPromise(prepareRuntime(f, f.run))).rejects.toThrow("Unexpected MCP endpoint requests: GET /version")
    await expect(fs.lstat(path.join(f.install, marker))).rejects.toMatchObject({ code: "ENOENT" })
    expect(await fs.realpath(f.active)).toBe(f.source)
  })

  it("leaves the active pointer and checkout untouched when prepare fails", async () => {
    const f = await fixture()
    const previous = path.join(f.directory, "previous")
    await fs.mkdir(previous)
    await fs.symlink(previous, f.active)
    await expect(Effect.runPromise(prepareRuntime(f, () => Effect.fail(new Error("install failed"))))).rejects.toThrow("install failed")
    expect(await fs.realpath(f.active)).toBe(previous)
    await expect(fs.lstat(path.join(f.install, marker))).rejects.toMatchObject({ code: "ENOENT" })
    for (const relative of ["dist", "node_modules", "extension/dist"]) {
      expect(await fs.readFile(path.join(f.source, relative, "untouched"), "utf8")).toBe("live")
    }
  })

  it("selects both bins together from a validated standalone copy and retains the previous install", async () => {
    const f = await fixture()
    await Effect.runPromise(prepareRuntime(f, f.run))
    const previous = path.join(f.directory, "previous")
    await fs.mkdir(previous)
    await fs.writeFile(path.join(previous, "retained"), "old runtime")
    await fs.symlink(previous, f.active)
    expect(await fs.realpath(f.active)).toBe(previous)
    await Effect.runPromise(selectRuntime(f))
    for (const [bin, file] of Object.entries({ "browser-control": "cli.js", "browser-control-mcp": "mcp.js" })) {
      expect(await fs.realpath(path.join(f.active, "bin", bin))).toBe(path.join(f.install, "node_modules", packageName, "dist", file))
    }
    expect(await fs.readFile(path.join(previous, "retained"), "utf8")).toBe("old runtime")
    await fs.rm(f.source, { recursive: true })
    await fs.rm(f.staging, { recursive: true })
    expect((await exec(path.join(f.active, "bin/browser-control"), ["--version"])).stdout.trim()).toBe("browser-control v1.2.3")
    await Effect.runPromise(selectRuntime(f))
  })

  it("refuses missing or modified candidates without touching the active pointer", async () => {
    const f = await fixture()
    await fs.symlink(f.source, f.active)
    await expect(Effect.runPromise(selectRuntime(f))).rejects.toThrow()
    expect(await fs.realpath(f.active)).toBe(f.source)
    await Effect.runPromise(prepareRuntime(f, f.run))
    await fs.appendFile(path.join(f.install, "node_modules", packageName, "dist/cli.js"), "// changed\n")
    await expect(Effect.runPromise(selectRuntime(f))).rejects.toThrow("changed since validation")
    expect(await fs.realpath(f.active)).toBe(f.source)
  })

  it("refuses plain active paths and existing prepare destinations", async () => {
    const f = await fixture()
    await Effect.runPromise(prepareRuntime(f, f.run))
    await fs.writeFile(f.active, "unrelated file")
    await expect(Effect.runPromise(selectRuntime(f))).rejects.toThrow("non-symlink")
    expect(await fs.readFile(f.active, "utf8")).toBe("unrelated file")
    await fs.unlink(f.active)
    await fs.mkdir(f.active)
    await expect(Effect.runPromise(selectRuntime(f))).rejects.toThrow("non-symlink")
    expect((await fs.lstat(f.active)).isDirectory()).toBe(true)
    await expect(Effect.runPromise(prepareRuntime(f, f.run))).rejects.toThrow("overwrite existing path")
  })

  it("rejects prepare inside the checkout and linked source inputs", async () => {
    const f = await fixture()
    await expect(Effect.runPromise(prepareRuntime({ ...f, staging: path.join(f.source, "stage") }, f.run))).rejects.toThrow("non-overlapping")
    await fs.symlink(path.join(f.source, "README.md"), path.join(f.source, "src/linked.ts"))
    await expect(Effect.runPromise(prepareRuntime(f, f.run))).rejects.toThrow("must not be a symlink")
  })

  it("does not stamp a candidate whose final installed validation fails", async () => {
    const f = await fixture()
    await expect(Effect.runPromise(prepareRuntime(f, (command, args, cwd, env) => args[0] === "--version" && !env
      ? Effect.succeed("wrong-version")
      : f.run(command, args, cwd, env)))).rejects.toThrow("CLI version mismatch")
    await expect(fs.lstat(path.join(f.install, marker))).rejects.toMatchObject({ code: "ENOENT" })
    await fs.symlink(f.source, f.active)
    await expect(Effect.runPromise(selectRuntime(f))).rejects.toThrow()
    expect(await fs.realpath(f.active)).toBe(f.source)
  })

  it("cleans the strict packed consumer and leaves the candidate unvalidated when its check fails", async () => {
    const f = await fixture()
    await expect(Effect.runPromise(prepareRuntime(f, (command, args, cwd, env) => command === "node" && env
      ? Effect.fail(new Error("packed Effect cohort mismatch"))
      : f.run(command, args, cwd, env)))).rejects.toThrow("packed Effect cohort mismatch")
    expect((await fs.readdir(f.directory)).some((name) => name.startsWith(".browser-control-pnpm-"))).toBe(false)
    await expect(fs.lstat(path.join(f.install, marker))).rejects.toMatchObject({ code: "ENOENT" })
  })
})

import fs from "node:fs/promises"
import os from "node:os"
import path from "node:path"
import { afterEach, describe, expect, it } from "vitest"
import { Effect } from "effect"
import * as AuthProfile from "../src/auth-profile.ts"
import { SecretProfile } from "../src/index.ts"

const temporaryDirectories: string[] = []

afterEach(async () => {
  await Promise.all(temporaryDirectories.splice(0).map((directory) => fs.rm(directory, { recursive: true, force: true })))
})

describe("AuthProfile", () => {
  it("writes restrictive profiles and returns metadata without values", async () => {
    const baseDir = await temporaryDirectory()
    const result = await Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "token-value", sources: ["request.header.authorization"] }],
    }))

    expect(result).toMatchObject({ name: "uber", slotCount: 1, slots: [{ ref: "BC_SECRET_1", expired: false }] })
    expect(JSON.stringify(result)).not.toContain("token-value")
    const publicStatus = await Effect.runPromise(SecretProfile.status("uber", { baseDir }))
    expect(publicStatus).toEqual(result)
    const stat = await fs.stat(path.join(baseDir, "uber.json"))
    expect(stat.mode & 0o777).toBe(0o600)
  })

  it("injects profile values and redacts them from child output", async () => {
    const baseDir = await temporaryDirectory()
    await Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "token-value", sources: ["request.header.authorization"] }],
    }))

    const result = await Effect.runPromise(SecretProfile.run({
      name: "uber",
      baseDir,
      command: process.execPath,
      args: ["-e", "process.stdout.write(process.env.BC_SECRET_1 || '')"],
    }))
    expect(result).toMatchObject({ exitCode: 0, stdout: "${BC_SECRET_1}", stderr: "" })
  })

  it("exposes a runtime error class and rejects unsafe worker bounds", async () => {
    const baseDir = await temporaryDirectory()

    await expect(Effect.runPromise(SecretProfile.run({
      name: "uber",
      baseDir,
      command: process.execPath,
      timeoutMs: 0,
    }))).rejects.toBeInstanceOf(SecretProfile.Error)
    await expect(Effect.runPromise(SecretProfile.run({
      name: "uber",
      baseDir,
      command: process.execPath,
      maxOutputBytes: -1,
    }))).rejects.toMatchObject({ _tag: "AuthProfile.Error", reason: "run-failed" })
  })

  it("does not leak a credential cut by the output budget", async () => {
    const baseDir = await temporaryDirectory()
    await Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "long-token-value", sources: ["request.header.authorization"] }],
    }))

    const result = await Effect.runPromise(AuthProfile.run({
      name: "uber",
      baseDir,
      maxOutputBytes: 8,
      command: process.execPath,
      args: ["-e", "process.stdout.write(process.env.BC_SECRET_1 || '')"],
    }))
    expect(result.stdout).toBe("")
    expect(result.stdoutTruncated).toBe(true)
  })

  it("updates an existing profile without changing its creation time", async () => {
    const baseDir = await temporaryDirectory()
    await Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "old", sources: ["request.header.authorization"] }],
    }))
    const before = await Effect.runPromise(AuthProfile.read("uber", { baseDir }))
    await Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "new", sources: ["request.header.authorization"] }],
    }))
    const after = await Effect.runPromise(AuthProfile.read("uber", { baseDir }))

    expect(after.createdAt).toBe(before.createdAt)
    expect(after.slots[0]?.value).toBe("new")
  })

  it("does not overwrite a malformed existing profile", async () => {
    const baseDir = await temporaryDirectory()
    const filePath = path.join(baseDir, "uber.json")
    await fs.writeFile(filePath, "not-json", { mode: 0o600 })

    await expect(Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "new", sources: ["request.header.authorization"] }],
    }))).rejects.toMatchObject({ _tag: "AuthProfile.Error", reason: "invalid-json" })
    await expect(fs.readFile(filePath, "utf8")).resolves.toBe("not-json")
  })

  it("terminates a timed-out credential-bearing process", async () => {
    const baseDir = await temporaryDirectory()
    await Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "token-value", sources: ["request.header.authorization"] }],
    }))

    const result = await Effect.runPromise(AuthProfile.run({
      name: "uber",
      baseDir,
      timeoutMs: 20,
      command: process.execPath,
      args: ["-e", "setInterval(() => {}, 1000)"],
    }))
    expect(result.exitCode).toBe(1)
    expect(result.signal).toMatch(/SIGTERM|SIGKILL/)
  })

  it("does not pass inherited Browser Control secret slots to the child", async () => {
    const baseDir = await temporaryDirectory()
    await Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "profile-token", sources: ["request.header.authorization"] }],
    }))
    process.env.BC_SECRET_999 = "inherited-token"
    try {
      const result = await Effect.runPromise(AuthProfile.run({
        name: "uber",
        baseDir,
        command: process.execPath,
        args: ["-e", "process.stdout.write(process.env.BC_SECRET_999 || '')"],
      }))
      expect(result.stdout).toBe("")
    } finally {
      delete process.env.BC_SECRET_999
    }
  })

  it("serializes profile transactions through a filesystem lock", async () => {
    const baseDir = await temporaryDirectory()
    let active = 0
    let maximumActive = 0
    const transaction = () => AuthProfile.withLock("uber", { baseDir }, Effect.gen(function* () {
      active += 1
      maximumActive = Math.max(maximumActive, active)
      yield* Effect.sleep(30)
      active -= 1
    }))

    await Promise.all([Effect.runPromise(transaction()), Effect.runPromise(transaction())])
    expect(maximumActive).toBe(1)
    await expect(fs.stat(path.join(baseDir, "uber.json.lock"))).rejects.toMatchObject({ code: "ENOENT" })
  })
})

async function temporaryDirectory(): Promise<string> {
  const directory = await fs.mkdtemp(path.join(os.tmpdir(), "browser-control-auth-"))
  temporaryDirectories.push(directory)
  return directory
}

import { describe, expect, it } from "vitest"
import { getHumanModelProfile, setHumanModelProfile, trajectory } from "../src/human-input.ts"
import {
  DEFAULT_HUMAN_MODEL_PROFILE,
  analyzeReach,
  fitHumanModel,
  type ObstacleRunPayload,
  type RecordedReach,
} from "../src/human-model.ts"

function makeSyntheticReach(options: {
  readonly from: { readonly x: number; readonly y: number }
  readonly to: { readonly x: number; readonly y: number }
  readonly durationMs: number
  readonly bowRatio: number
  readonly overshootPx?: number
}): RecordedReach {
  const { from, to, durationMs, bowRatio, overshootPx = 0 } = options
  const dx = to.x - from.x
  const dy = to.y - from.y
  const dist = Math.hypot(dx, dy)
  const tx = dx / dist
  const ty = dy / dist
  const nx = -ty
  const ny = tx
  const samples = Array.from({ length: 24 }, (_, idx) => {
    const u = idx / 23
    const t = u * durationMs
    let par: number
    if (overshootPx > 0) {
      const split = 0.8
      if (u <= split) {
        const localU = Math.pow(u / split, 0.72)
        const jerk = localU * localU * localU * (10 - 15 * localU + 6 * localU * localU)
        par = (dist + overshootPx) * jerk
      } else {
        const localU = (u - split) / (1 - split)
        const jerk = localU * localU * localU * (10 - 15 * localU + 6 * localU * localU)
        par = dist + overshootPx - overshootPx * jerk
      }
    } else {
      const s = Math.pow(u, 0.72)
      const jerk = s * s * s * (10 - 15 * s + 6 * s * s)
      par = dist * jerk
    }
    const perp = bowRatio * dist * Math.sin(Math.PI * u) + Math.sin(u * Math.PI * 5) * 0.9
    return {
      x: from.x + tx * par + nx * perp,
      y: from.y + ty * par + ny * perp,
      t,
    }
  })
  return {
    from,
    to,
    targetCenter: { x: to.x - 1.4, y: to.y + 0.9 },
    targetWidth: 42,
    targetHeight: 36,
    durationMs,
    settleMs: 28,
    holdMs: 62,
    samples,
  }
}

describe("human-model fitting and calibration", () => {
  it("analyzes reach curvature, velocity peak, and overshoot submovements", () => {
    const direct = analyzeReach(
      makeSyntheticReach({
        from: { x: 100, y: 200 },
        to: { x: 520, y: 240 },
        durationMs: 240,
        bowRatio: -0.075,
      }),
    )
    expect(direct).toBeDefined()
    expect(direct!.distance).toBeGreaterThan(400)
    expect(direct!.pathRatio).toBeGreaterThan(1.01)
    expect(direct!.bowRatio).toBeGreaterThan(0.05)
    expect(direct!.peakVelocityU).toBeLessThan(0.48)
    expect(direct!.mode).toBe("direct")

    const overshot = analyzeReach(
      makeSyntheticReach({
        from: { x: 80, y: 120 },
        to: { x: 560, y: 310 },
        durationMs: 260,
        bowRatio: 0.06,
        overshootPx: 7.5,
      }),
    )
    expect(overshot?.mode).toBe("overshoot")
    expect(overshot?.overshootPx).toBeGreaterThan(4)
  })

  it("fits a computational model from team obstacle course runs and drives trajectory()", () => {
    const run: ObstacleRunPayload = {
      handle: "kit",
      device: "mouse",
      sampleRateHz: 120,
      viewport: { width: 1440, height: 900, dpr: 2 },
      courseTimeMs: 38_400,
      reaches: [
        makeSyntheticReach({ from: { x: 100, y: 120 }, to: { x: 460, y: 180 }, durationMs: 210, bowRatio: -0.06 }),
        makeSyntheticReach({ from: { x: 460, y: 180 }, to: { x: 180, y: 420 }, durationMs: 245, bowRatio: 0.08, overshootPx: 6.2 }),
        makeSyntheticReach({ from: { x: 180, y: 420 }, to: { x: 740, y: 360 }, durationMs: 270, bowRatio: -0.07 }),
        makeSyntheticReach({ from: { x: 740, y: 360 }, to: { x: 640, y: 280 }, durationMs: 165, bowRatio: 0.05 }),
      ],
      scrolls: [
        {
          totalDeltaX: 0,
          totalDeltaY: 680,
          durationMs: 150,
          frameCount: 9,
          frames: Array.from({ length: 9 }, () => ({ dx: 0, dy: 75, dt: 16 })),
        },
      ],
      keys: [
        { key: "s", holdMs: 64, ikiMs: 88, rolloverMs: 12 },
        { key: "h", holdMs: 58, ikiMs: 76, rolloverMs: 8 },
        { key: "i", holdMs: 61, ikiMs: 82, rolloverMs: -4 },
        { key: "p", holdMs: 70, ikiMs: 95, rolloverMs: 0 },
      ],
    }

    const fitted = fitHumanModel([run], "team-kit")
    expect(fitted.sampleCount.runs).toBe(1)
    expect(fitted.sampleCount.reaches).toBe(4)
    expect(fitted.reach.ballisticExponent).toBeGreaterThan(0.58)
    expect(fitted.reach.ballisticExponent).toBeLessThan(0.92)
    expect(fitted.velocityCurve).toHaveLength(20)

    setHumanModelProfile(fitted)
    expect(getHumanModelProfile().source).toBe("team-kit")
    const steps = trajectory({ x: 80, y: 90 }, { x: 540, y: 320 })
    expect(steps.length).toBeGreaterThan(5)
    setHumanModelProfile(DEFAULT_HUMAN_MODEL_PROFILE)
  })
})

import http from "node:http"
import { afterAll, beforeAll, beforeEach, describe, expect, it } from "vitest"
