  })

  it("attaches explicit execute images without duplicating base64 in metadata", () => {
    const result = toolResultForValue({
      text: "Image (image/png, 4 bytes)",
      media: [
        { type: "image", mimeType: "image/png", data: Buffer.from([1, 2]).toString("base64"), size: 2 },
        { type: "image", mimeType: "image/png", data: Buffer.from([3, 4]).toString("base64"), size: 2 },
      ],
      isError: false,
      logs: [],
      session: { id: "mcp-test" },
    })

    expect(result.content).toHaveLength(3)
    expect(result.content[0]).toMatchObject({ type: "text" })
    expect(result.content[1]).toMatchObject({ type: "image", mimeType: "image/png" })
    expect(Array.from(result.content[1]?.type === "image" ? result.content[1].data : [])).toEqual([1, 2])
    expect(Array.from(result.content[2]?.type === "image" ? result.content[2].data : [])).toEqual([3, 4])
    expect(result.structuredContent).not.toHaveProperty("media")
  })
})

import { describe, expect, it } from "vitest"
import { canClientSeeTarget } from "../src/cdp-visibility.ts"
import { TargetRegistry } from "../src/target-registry.ts"
import type { ChildTarget, ConnectedTarget } from "../src/relay-types.ts"
import type { TargetInfo } from "../src/protocol.ts"

function targetInfo(targetId: string, url = "https://example.com/"): TargetInfo {
  return { targetId, type: "page", title: "t", url, attached: true, canAccessOpener: false }
}

function rootTarget(options: {
  readonly tabId: number
  readonly sessionId: string
  readonly browserControlSessionId?: string
}): ConnectedTarget {
  return {
    tabId: options.tabId,
    sessionId: options.sessionId,
    targetInfo: targetInfo(`target-${options.tabId}`),
    owner: options.browserControlSessionId ? "relay" : "user",
    ...(options.browserControlSessionId ? { browserControlSessionId: options.browserControlSessionId } : {}),
  }
}

describe("canClientSeeTarget", () => {
  it("shows user toolbar targets to every client", () => {
    expect(canClientSeeTarget({ clientSessionId: "session-a", targetOwnerSessionId: undefined, targetOwner: "user", clientHasOwnedTarget: true })).toBe(true)
    expect(canClientSeeTarget({ clientSessionId: undefined, targetOwnerSessionId: undefined, targetOwner: "user", clientHasOwnedTarget: false })).toBe(true)
  })

  it("shows session-owned targets only to that session's clients", () => {
    expect(canClientSeeTarget({ clientSessionId: "session-a", targetOwnerSessionId: "session-a", targetOwner: "relay", clientHasOwnedTarget: true })).toBe(true)
    expect(canClientSeeTarget({ clientSessionId: "session-b", targetOwnerSessionId: "session-a", targetOwner: "relay", clientHasOwnedTarget: false })).toBe(false)
  })

  it("hides session-owned targets from raw clients so they cannot double-initialize them", () => {
    expect(canClientSeeTarget({ clientSessionId: undefined, targetOwnerSessionId: "session-a", targetOwner: "relay", clientHasOwnedTarget: false })).toBe(false)
  })

  it("hides raw-client-created targets from session clients that already own a target while keeping target-url discovery available", () => {
    expect(canClientSeeTarget({ clientSessionId: undefined, targetOwnerSessionId: undefined, targetOwner: "relay", clientHasOwnedTarget: false })).toBe(true)
    expect(canClientSeeTarget({ clientSessionId: "session-a", targetOwnerSessionId: undefined, targetOwner: "relay", clientHasOwnedTarget: false })).toBe(true)
    expect(canClientSeeTarget({ clientSessionId: "session-a", targetOwnerSessionId: undefined, targetOwner: "relay", clientHasOwnedTarget: true })).toBe(false)
  })
})

describe("TargetRegistry.allTargetInfos visibility filter", () => {
  it("filters root and child targets through isVisibleTarget", () => {
    const registry = new TargetRegistry()
    const owned = rootTarget({ tabId: 1, sessionId: "bc-tab-1", browserControlSessionId: "session-a" })
    const unowned = rootTarget({ tabId: 2, sessionId: "bc-tab-2" })
    registry.addRootTarget(owned)
    registry.addRootTarget(unowned)
    const child: ChildTarget = {
      tabId: 1,
      sessionId: "child-1",
      parentSessionId: "bc-tab-1",
      targetInfo: targetInfo("child-target-1"),
      waitingForDebugger: false,
    }
    registry.addChildTarget(child)

    const canSee = (clientSessionId: string | undefined) => {
      return registry
        .allTargetInfos({
          isRestrictedTarget: () => false,
          isVisibleTarget: (target) => {
            const root = registry.tabTargets.get(target.tabId)
            return canClientSeeTarget({
              clientSessionId,
              targetOwnerSessionId: root?.browserControlSessionId,
              targetOwner: root?.owner ?? "relay",
              clientHasOwnedTarget: clientSessionId === "session-a",
            })
          },
        })
        .map((info) => info.targetId)
    }

    expect(canSee("session-a")).toEqual(["target-1", "target-2", "child-target-1"])
    expect(canSee("session-b")).toEqual(["target-2"])
    expect(canSee(undefined)).toEqual(["target-2"])
  })
})

import { describe, expect, it } from "vitest"
import { guardCdpMethod } from "../src/cdp-guardrails.ts"

describe("cdp-guardrails", () => {
  it("always blocks browser-state-destroying methods", () => {
    for (const method of ["Network.clearBrowserCookies", "Network.clearBrowserCache", "Storage.clearCookies", "Browser.close"]) {
      const message = guardCdpMethod({ method, readOnly: false })
      expect(message).toContain(`Browser Control blocked ${method}`)
      expect(message).toContain("always blocked")
    }
  })

  it("allows ordinary methods", () => {
    for (const method of ["Page.navigate", "Runtime.evaluate", "Target.createTarget", "Network.enable", "Input.dispatchMouseEvent"]) {
      expect(guardCdpMethod({ method, readOnly: false })).toBeNull()
    }
  })

  it("blocks input dispatch for read-only sessions with the session id in the message", () => {
    const message = guardCdpMethod({ method: "Input.dispatchMouseEvent", readOnly: true, sessionId: "quiet-owl-1" })
    expect(message).toContain("Session quiet-owl-1 is read-only")
    expect(message).toContain("Input.dispatchMouseEvent")
  })

  it("blocks all Input.* methods in read-only mode but allows reads", () => {
    expect(guardCdpMethod({ method: "Input.dispatchKeyEvent", readOnly: true })).not.toBeNull()
    expect(guardCdpMethod({ method: "Input.insertText", readOnly: true })).not.toBeNull()
    expect(guardCdpMethod({ method: "Runtime.evaluate", readOnly: true })).toBeNull()
    expect(guardCdpMethod({ method: "Page.captureScreenshot", readOnly: true })).toBeNull()
  })
})

import { describe, expect, it } from "vitest"
import type { WebSocket } from "ws"
import { CdpClientPool } from "../src/cdp-client-pool.ts"
import { replayChildTargetsForParent } from "../src/cdp-shims.ts"
import type { ChildTarget, ConnectedTarget } from "../src/relay-types.ts"
import { parseJsonObject, type JsonObject, type TargetInfo } from "../src/protocol.ts"
import { sendCdpEvent } from "../src/relay-helpers.ts"
import { TargetRegistry } from "../src/target-registry.ts"

function setup() {
  const events: JsonObject[] = []
  const socket: Pick<WebSocket, "send"> = {
    send(data) {
      if (typeof data !== "string") throw new Error("Expected a serialized CDP event")
      events.push(parseJsonObject(data))
    },
  }
  const clients = new CdpClientPool<typeof socket>(sendCdpEvent, () => {})
  clients.register(socket)
  return { socket, clients, events, registry: new TargetRegistry() }
}

function targetInfo(targetId: string): TargetInfo {
  return { targetId, type: "page", title: "title", url: "https://example.com/", attached: true, canAccessOpener: false }
}

function root(sessionId: string, targetId = "target-1"): ConnectedTarget {
  return { tabId: 1, sessionId, targetInfo: targetInfo(targetId), owner: "user" }
}

function child(sessionId: string, targetId = "child-target-1", parentSessionId = "bc-tab-1"): ChildTarget {
  return { tabId: 1, sessionId, parentSessionId, targetInfo: { ...targetInfo(targetId), type: "iframe" }, waitingForDebugger: false }
}

describe("TargetRegistry crash state", () => {
  it("marks a root target crashed and clears the marker after navigation", () => {
    const registry = new TargetRegistry()
    registry.addRootTarget(root("bc-tab-1"))

    expect(registry.markRootTargetCrashed(1)?.crashed).toBe(true)
    expect(registry.getRootTargetByTabId(1)?.crashed).toBe(true)

    registry.updateTargetUrl(1, "https://example.com/recovered")
    expect(registry.getRootTargetByTabId(1)?.crashed).toBe(false)
  })
})

describe("replayChildTargetsForParent", () => {
  it("replays dedicated workers without synthesizing iframe navigation events", () => {
    const { socket, clients, events, registry } = setup()
    registry.addChildTarget({
      ...child("worker-session", "worker-target"),
      targetInfo: { ...targetInfo("worker-target"), type: "worker", url: "https://example.com/worker.js" },
      waitingForDebugger: true,
    })

    replayChildTargetsForParent({
      socket,
      parentSessionId: "bc-tab-1",
      registry,
      clients,
    })

    expect(events).toHaveLength(1)
    expect(events[0]).toMatchObject({
      sessionId: "bc-tab-1",
      method: "Target.attachedToTarget",
      params: { sessionId: "worker-session", waitingForDebugger: true, targetInfo: { type: "worker" } },
    })
  })

  it("does not replay a held URL-less page child", () => {
    const { socket, clients, events, registry } = setup()
    registry.addChildTarget({
      ...child("held-session", "held-target"),
      targetInfo: { ...targetInfo("held-target"), type: "page", url: "" },
    })

    replayChildTargetsForParent({
      socket,
      parentSessionId: "bc-tab-1",
      registry,
      clients,
    })

    expect(events).toEqual([])
    expect(clients.hasSession(socket, "held-session")).toBe(false)
  })

  it("replays iframe parent events before attachment and navigation on the child session", () => {
    const { socket, clients, events, registry } = setup()
    const target = child("iframe-session")
    registry.addChildTarget(target)
    registry.addChildTarget(child("unrelated-session", "unrelated-target", "other-parent"))
    const attached = { frameId: target.targetInfo.targetId, parentFrameId: "root-frame" }
    const navigated = { frame: { id: target.targetInfo.targetId, parentId: "root-frame", url: "https://example.com/stale" } }
    registry.rememberFrameEvent({ tabId: 1, frameId: target.targetInfo.targetId, attached, navigated })

    replayChildTargetsForParent({ socket, parentSessionId: "bc-tab-1", registry, clients })

    expect(events).toEqual([
      { sessionId: "bc-tab-1", method: "Page.frameAttached", params: attached },
      { sessionId: "bc-tab-1", method: "Page.frameNavigated", params: navigated },
      {
        sessionId: "bc-tab-1",
        method: "Target.attachedToTarget",
        params: { sessionId: target.sessionId, targetInfo: target.targetInfo, waitingForDebugger: false },
      },
      {
        sessionId: target.sessionId,
        method: "Page.frameNavigated",
        params: { frame: { ...navigated.frame, url: target.targetInfo.url } },
      },
    ])
    expect(clients.hasSession(socket, target.sessionId)).toBe(true)
    expect(clients.hasSession(socket, "unrelated-session")).toBe(false)
  })

  it("synthesizes child iframe navigation from target info when no frame event was retained", () => {
    const { socket, clients, events, registry } = setup()
    const target = child("iframe-session")
    registry.addChildTarget(target)

    replayChildTargetsForParent({ socket, parentSessionId: "bc-tab-1", registry, clients })

    expect(events.map((event) => event.method)).toEqual(["Target.attachedToTarget", "Page.frameNavigated"])
    expect(events[1]).toMatchObject({
      sessionId: target.sessionId,
      params: { frame: { id: target.targetInfo.targetId, url: target.targetInfo.url, securityOrigin: "https://example.com" } },
    })
  })
})

import { describe, expect, it } from "vitest"
import { CdpClientPool, ClientCdpSessionAlias } from "../src/cdp-client-pool.ts"
import type { CdpEvent } from "../src/protocol.ts"
import type { ChildTarget, ConnectedTarget } from "../src/relay-types.ts"

const rootTarget: ConnectedTarget = {
  tabId: 7,
  sessionId: "bc-tab-7",
  targetInfo: {
    targetId: "root-7",
    type: "page",
    title: "Root",
    url: "https://example.com/",
    attached: true,
    canAccessOpener: false,
  },
  owner: "user",
}

const childTarget: ChildTarget = {
  tabId: 7,
  sessionId: "chrome-child-7",
  parentSessionId: "bc-tab-7",
  targetInfo: {
    targetId: "child-7",
    type: "iframe",
    title: "Child",
    url: "https://child.example.com/",
    attached: true,
    canAccessOpener: false,
  },
  waitingForDebugger: false,
}

const grandchildTarget: ChildTarget = {
  ...childTarget,
  sessionId: "chrome-grandchild-7",
  parentSessionId: childTarget.sessionId,
  targetInfo: { ...childTarget.targetInfo, targetId: "grandchild-7" },
}

function setup() {
  const retired: Array<{ readonly client: { events: CdpEvent[] }; readonly sessionId: string }> = []
  const pool = new CdpClientPool<{ events: CdpEvent[] }>((client, event) => client.events.push(event), (client, sessionId) => retired.push({ client, sessionId }))
  const client: { events: CdpEvent[] } = { events: [] }
  pool.register(client)
  return { pool, client, events: client.events, retired }
}

describe("CdpClientPool", () => {
  it("treats named external clients as raw unless they identify a sandbox transport", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const named = {}, sandbox = {}, unnamed = {}
    pool.register(named, "alpha")
    pool.register(sandbox, "alpha", "sandbox")
    pool.register(unnamed, undefined, "sandbox")
    expect(pool.isSandbox(named)).toBe(false)
    expect(pool.isSandbox(sandbox)).toBe(true)
    expect(pool.isSandbox(unnamed)).toBe(false)
    pool.unregister(sandbox)
    expect(pool.isSandbox(sandbox)).toBe(false)
  })
  it("owns registration and cleanup for all per-client state", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const client = {}
    pool.register(client, "session-a")
    pool.setAutoAttachParams(client, { autoAttach: true, flatten: true })
    const aliasId = pool.createBrowserAlias(client)
    pool.announce(client, rootTarget)

    expect(pool.size).toBe(1)
    expect([...pool]).toEqual([client])
    expect(pool.sessionId(client)).toBe("session-a")
    expect(pool.autoAttachParams(client)).toEqual({ autoAttach: true, flatten: true })
    expect(pool.alias(client, aliasId)).toEqual(ClientCdpSessionAlias.Browser())
    expect(pool.hasSession(client, rootTarget.sessionId)).toBe(true)

    expect(pool.unregister(client)).toBeTypeOf("number")
    expect(pool.size).toBe(0)
    expect(pool.sessionId(client)).toBeUndefined()
    expect(pool.alias(client, aliasId)).toBeUndefined()
    expect(pool.autoAttachParams(client)).toBeUndefined()
    expect(pool.hasSession(client, rootTarget.sessionId)).toBe(false)

    pool.register(client)
    expect(pool.hasSession(client, rootTarget.sessionId)).toBe(false)
    expect(pool.alias(client, aliasId)).toBeUndefined()
  })

  it("keeps conflicting auto-attach settings scoped to their clients", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const first = {}
    const second = {}
    pool.register(first)
    pool.register(second)
    pool.setAutoAttachParams(first, { autoAttach: true, waitForDebuggerOnStart: false })
    pool.setAutoAttachParams(second, { autoAttach: false, waitForDebuggerOnStart: true })

    expect(pool.autoAttachParams(first)).toEqual({ autoAttach: true, waitForDebuggerOnStart: false })
    expect(pool.autoAttachParams(second)).toEqual({ autoAttach: false, waitForDebuggerOnStart: true })
    pool.setAutoAttachParams(first, undefined)
    expect(pool.autoAttachParams(first)).toBeUndefined()
    expect(pool.autoAttachParams(second)).toEqual({ autoAttach: false, waitForDebuggerOnStart: true })
  })

  it("rejects duplicate registration and aliases for unknown clients", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const client = {}
    pool.register(client)

    expect(() => pool.register(client)).toThrow("CDP client is already registered")
    expect(() => pool.createBrowserAlias({})).toThrow("CDP client is not registered")
    expect(() => pool.announce({}, rootTarget)).toThrow("CDP client is not registered")
  })

  it("invalidates an idle generation when another client registers", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const first = {}
    pool.register(first)
    const idleGeneration = pool.unregister(first)
    expect(idleGeneration).toBeDefined()
    if (idleGeneration === undefined) throw new Error("Expected idle generation")
    expect(pool.isCurrentIdleGeneration(idleGeneration)).toBe(true)

    pool.register({})
    expect(pool.isCurrentIdleGeneration(idleGeneration)).toBe(false)
  })

  it("produces an idle generation only when the last client leaves", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const first = {}
    const second = {}
    pool.register(first)
    pool.register(second)

    expect(pool.unregister(first)).toBeUndefined()
    const idleGeneration = pool.unregister(second)
    expect(idleGeneration).toBeDefined()
    expect(pool.unregister(second)).toBeUndefined()
  })

  it("routes root aliases without a Chrome session and child aliases with one", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const client = {}
    pool.register(client)

    const rootAlias = pool.createTargetAlias(client, rootTarget)
    const childAlias = pool.createTargetAlias(client, childTarget)

    expect(pool.alias(client, rootAlias)).toEqual(ClientCdpSessionAlias.Target({ tabId: 7, targetId: "root-7" }))
    expect(pool.alias(client, childAlias)).toEqual(ClientCdpSessionAlias.Target({
      tabId: 7,
      targetId: "child-7",
      chromeSessionId: "chrome-child-7",
    }))
  })

  it("detaches alias-only tabs across clients without touching browser aliases or other tabs", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const first = {}
    const second = {}
    pool.register(first)
    pool.register(second)
    const browserAlias = pool.createBrowserAlias(first)
    const firstTargetAlias = pool.createTargetAlias(first, rootTarget)
    const secondTargetAlias = pool.createTargetAlias(second, childTarget)
    const otherAlias = pool.createTargetAlias(first, {
      ...rootTarget,
      tabId: 8,
      sessionId: "bc-tab-8",
      targetInfo: { ...rootTarget.targetInfo, targetId: "root-8" },
    })

    pool.detachTab(7)
    pool.detachTab(7)

    expect(pool.alias(first, browserAlias)).toEqual(ClientCdpSessionAlias.Browser())
    expect(pool.alias(first, firstTargetAlias)).toBeUndefined()
    expect(pool.alias(second, secondTargetAlias)).toBeUndefined()
    expect(pool.alias(first, otherAlias)).toBeDefined()
  })

  it("prunes hidden alias-only targets for one client without touching another client", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const first = {}
    const second = {}
    pool.register(first)
    pool.register(second)
    const firstAlias = pool.createTargetAlias(first, rootTarget)
    const secondAlias = pool.createTargetAlias(second, rootTarget)
    const browserAlias = pool.createBrowserAlias(first)

    pool.pruneInvisible(first, (tabId) => tabId !== 7)

    expect(pool.alias(first, firstAlias)).toBeUndefined()
    expect(pool.alias(second, secondAlias)).toBeDefined()
    expect(pool.alias(first, browserAlias)).toEqual(ClientCdpSessionAlias.Browser())
  })

  it("announces roots and children once per client with the correct parent envelope", () => {
    const { pool, client, events } = setup()
    const other: { events: CdpEvent[] } = { events: [] }
    pool.register(other)

    pool.announce(client, rootTarget)
    pool.announce(client, rootTarget)
    pool.announce(client, childTarget)
    pool.announce(client, childTarget)

    expect(events).toEqual([
      {
        method: "Target.attachedToTarget",
        params: { sessionId: rootTarget.sessionId, targetInfo: rootTarget.targetInfo, waitingForDebugger: false },
      },
      {
        sessionId: rootTarget.sessionId,
        method: "Target.attachedToTarget",
        params: { sessionId: childTarget.sessionId, targetInfo: childTarget.targetInfo, waitingForDebugger: false },
      },
    ])
    expect(other.events).toEqual([])
    expect(pool.hasSession(other, rootTarget.sessionId)).toBe(false)

    pool.announce(other, rootTarget)
    expect(other.events).toEqual([events[0]])
    expect(events).toHaveLength(2)
  })

  it("replaces the same target id under a new session after purging descendants and aliases", () => {
    const { pool, client, events } = setup()
    const aliases = [rootTarget, childTarget, grandchildTarget].map((target) => {
      pool.announce(client, target)
      return pool.createTargetAlias(client, target)
    })
    const browserAlias = pool.createBrowserAlias(client)
    events.length = 0

    pool.announce(client, { ...rootTarget, sessionId: "replacement-root-session" })

    expect(events).toEqual([
      {
        sessionId: childTarget.sessionId,
        method: "Target.detachedFromTarget",
        params: { sessionId: grandchildTarget.sessionId, targetId: grandchildTarget.targetInfo.targetId },
      },
      {
        sessionId: rootTarget.sessionId,
        method: "Target.detachedFromTarget",
        params: { sessionId: childTarget.sessionId, targetId: childTarget.targetInfo.targetId },
      },
      {
        method: "Target.detachedFromTarget",
        params: { sessionId: rootTarget.sessionId, targetId: rootTarget.targetInfo.targetId },
      },
      {
        method: "Target.attachedToTarget",
        params: { sessionId: "replacement-root-session", targetInfo: rootTarget.targetInfo, waitingForDebugger: false },
      },
    ])
    for (const target of [rootTarget, childTarget, grandchildTarget]) {
      expect(pool.hasSession(client, target.sessionId)).toBe(false)
    }
    for (const alias of aliases) expect(pool.alias(client, alias)).toBeUndefined()
    expect(pool.alias(client, browserAlias)).toEqual(ClientCdpSessionAlias.Browser())
    expect(pool.hasSession(client, "replacement-root-session")).toBe(true)
  })

  it("clears the previous identity when a session id is reused for a different target", () => {
    const { pool, client, events } = setup()
    pool.announce(client, rootTarget)
    pool.announce(client, childTarget)
    const rootAlias = pool.createTargetAlias(client, rootTarget)
    const childAlias = pool.createTargetAlias(client, childTarget)
    const replacement = { ...rootTarget, targetInfo: { ...rootTarget.targetInfo, targetId: "replacement-target" } }
    events.length = 0

    pool.announce(client, replacement)
    pool.announce(client, replacement)

    expect(events.map((event) => [event.method, event.params?.sessionId])).toEqual([
      ["Target.detachedFromTarget", childTarget.sessionId],
      ["Target.detachedFromTarget", rootTarget.sessionId],
      ["Target.attachedToTarget", rootTarget.sessionId],
    ])
    expect(events[1]?.params?.targetId).toBe(rootTarget.targetInfo.targetId)
    expect(events[2]?.params?.targetInfo).toEqual(replacement.targetInfo)
    expect(pool.alias(client, rootAlias)).toBeUndefined()
    expect(pool.alias(client, childAlias)).toBeUndefined()
    expect(pool.hasSession(client, childTarget.sessionId)).toBe(false)
    expect(pool.hasSession(client, rootTarget.sessionId)).toBe(true)
  })

  it("detaches duplicate child target ids on the old parent before re-announcing", () => {
    const { pool, client, events } = setup()
    pool.announce(client, childTarget)
    const alias = pool.createTargetAlias(client, childTarget)
    events.length = 0
    const replacement = { ...childTarget, sessionId: "replacement-child", parentSessionId: "replacement-parent" }

    pool.announce(client, replacement)

    expect(events).toEqual([
      {
        sessionId: rootTarget.sessionId,
        method: "Target.detachedFromTarget",
        params: { sessionId: childTarget.sessionId, targetId: childTarget.targetInfo.targetId },
      },
      {
        sessionId: "replacement-parent",
        method: "Target.attachedToTarget",
        params: { sessionId: "replacement-child", targetInfo: childTarget.targetInfo, waitingForDebugger: false },
      },
    ])
    expect(pool.alias(client, alias)).toBeUndefined()
    expect(pool.hasSession(client, childTarget.sessionId)).toBe(false)
    expect(pool.hasSession(client, replacement.sessionId)).toBe(true)
  })

  it.each([false, true])("detaches a tab's descendants before its root, idempotently (destroyed=%s)", (destroyed) => {
    const { pool, client, events } = setup()
    const other: { events: CdpEvent[] } = { events: [] }
    pool.register(other)
    for (const target of [rootTarget, childTarget, grandchildTarget]) pool.announce(client, target)
    events.length = 0

    pool.detachTab(rootTarget.tabId, { destroyed })
    pool.detachTab(rootTarget.tabId, { destroyed })

    expect(events.map((event) => [event.method, event.params?.targetId])).toEqual([
      ["Target.detachedFromTarget", grandchildTarget.targetInfo.targetId],
      ["Target.detachedFromTarget", childTarget.targetInfo.targetId],
      ...(destroyed ? [["Target.targetDestroyed", rootTarget.targetInfo.targetId]] : []),
      ["Target.detachedFromTarget", rootTarget.targetInfo.targetId],
    ])
    expect(events[0]?.sessionId).toBe(childTarget.sessionId)
    expect(events[1]?.sessionId).toBe(rootTarget.sessionId)
    expect(events.at(-1)?.sessionId).toBeUndefined()
    for (const target of [rootTarget, childTarget, grandchildTarget]) {
      expect(pool.hasSession(client, target.sessionId)).toBe(false)
    }
    expect(other.events).toEqual([])
  })

  it.each([false, true])("detaches a child subtree and its aliases without detaching the root (notify=%s)", (notify) => {
    const { pool, client, events } = setup()
    for (const target of [rootTarget, childTarget, grandchildTarget]) pool.announce(client, target)
    const rootAlias = pool.createTargetAlias(client, rootTarget)
    const childAlias = pool.createTargetAlias(client, childTarget)
    const grandchildAlias = pool.createTargetAlias(client, grandchildTarget)
    events.length = 0

    pool.detachTarget(childTarget, { notify })
    pool.detachTarget(childTarget, { notify })

    expect(events.map((event) => [event.method, event.params?.sessionId])).toEqual(notify ? [
      ["Target.detachedFromTarget", grandchildTarget.sessionId],
      ["Target.detachedFromTarget", childTarget.sessionId],
    ] : [])
    expect(pool.hasSession(client, rootTarget.sessionId)).toBe(true)
    expect(pool.hasSession(client, childTarget.sessionId)).toBe(false)
    expect(pool.hasSession(client, grandchildTarget.sessionId)).toBe(false)
    expect(pool.alias(client, rootAlias)).toBeDefined()
    expect(pool.alias(client, childAlias)).toBeUndefined()
    expect(pool.alias(client, grandchildAlias)).toBeUndefined()
  })

  it("removes an unannounced child alias on target detach", () => {
    const { pool, client, events } = setup()
    const alias = pool.createTargetAlias(client, childTarget)

    pool.detachTarget(childTarget)

    expect(pool.alias(client, alias)).toBeUndefined()
    expect(events).toEqual([])
  })

  it("silently detaches a client-requested alias without detaching the real session", () => {
    const { pool, client, events, retired } = setup()
    pool.announce(client, rootTarget)
    pool.announce(client, childTarget)
    const rootAlias = pool.createTargetAlias(client, rootTarget)
    const childAlias = pool.createTargetAlias(client, childTarget)
    const browserAlias = pool.createBrowserAlias(client)
    events.length = 0

    for (const alias of [rootAlias, childAlias, browserAlias]) {
      pool.detach(client, alias)
      pool.detach(client, alias)
      expect(pool.alias(client, alias)).toBeUndefined()
    }

    expect(pool.hasSession(client, rootTarget.sessionId)).toBe(true)
    expect(pool.hasSession(client, childTarget.sessionId)).toBe(true)
    expect(events).toEqual([])
    expect(retired).toEqual([])
  })

  it.each(["root", "child"])("silently detaches a client-requested %s subtree only for that client and reports retired canonical sessions", (kind) => {
    const { pool, client, events, retired } = setup()
    const other: { events: CdpEvent[] } = { events: [] }
    pool.register(other)
    const browserAlias = pool.createBrowserAlias(client)
    const aliases = [rootTarget, childTarget, grandchildTarget].map((target) => {
      pool.announce(client, target)
      pool.announce(other, target)
      return pool.createTargetAlias(client, target)
    })
    events.length = 0
    other.events.length = 0

    const detached = kind === "root" ? rootTarget : childTarget
    pool.detach(client, detached.sessionId)
    pool.detach(client, detached.sessionId)
    pool.detach(client, "unannounced-session")
    expect(retired).toEqual([
      grandchildTarget.sessionId, childTarget.sessionId, ...(kind === "root" ? [rootTarget.sessionId] : []),
    ].map((sessionId) => ({ client, sessionId })))

    for (const target of [rootTarget, childTarget, grandchildTarget]) {
      expect(pool.hasSession(client, target.sessionId)).toBe(kind === "child" && target === rootTarget)
      expect(pool.hasSession(other, target.sessionId)).toBe(true)
    }
    for (const [index, alias] of aliases.entries()) {
      expect(pool.alias(client, alias) !== undefined).toBe(kind === "child" && index === 0)
    }
    expect(pool.alias(client, browserAlias)).toEqual(ClientCdpSessionAlias.Browser())
    expect(events).toEqual([])
    expect(other.events).toEqual([])
  })

  it("delivers events only to announced visible clients and prunes hidden subtrees", () => {
    const { pool, client, events, retired } = setup()
    const hidden: { events: CdpEvent[] } = { events: [] }
    const unannounced: { events: CdpEvent[] } = { events: [] }
    pool.register(hidden)
    pool.register(unannounced)
    for (const target of [rootTarget, childTarget]) {
      pool.announce(client, target)
      pool.announce(hidden, target)
    }
    const visibleAlias = pool.createTargetAlias(client, childTarget)
    const hiddenAlias = pool.createTargetAlias(hidden, childTarget)
    const browserAlias = pool.createBrowserAlias(hidden)
    events.length = 0
    hidden.events.length = 0
    const event: CdpEvent = { sessionId: childTarget.sessionId, method: "Runtime.executionContextsCleared", params: {} }

    pool.sendToViewers(rootTarget.sessionId, event, (viewer, tabId) => viewer !== hidden && tabId === 7)

    expect(events).toEqual([event])
    expect(unannounced.events).toEqual([])
    expect(hidden.events.map((event) => [event.method, event.params?.sessionId])).toEqual([
      ["Target.detachedFromTarget", childTarget.sessionId],
      ["Target.detachedFromTarget", rootTarget.sessionId],
    ])
    expect(pool.hasSession(hidden, rootTarget.sessionId)).toBe(false)
    expect(pool.hasSession(hidden, childTarget.sessionId)).toBe(false)
    // Announced retirements report through the same sink as silent ones.
    expect(retired).toEqual([childTarget.sessionId, rootTarget.sessionId].map((sessionId) => ({ client: hidden, sessionId })))
    expect(pool.alias(hidden, hiddenAlias)).toBeUndefined()
    expect(pool.alias(hidden, browserAlias)).toEqual(ClientCdpSessionAlias.Browser())
    expect(pool.alias(client, visibleAlias)).toBeDefined()

    hidden.events.length = 0
    pool.sendToViewers(rootTarget.sessionId, event, () => true)
    expect(hidden.events).toEqual([])
    expect(unannounced.events).toEqual([])
    expect(events).toEqual([event, event])
  })
})

import { describe, expect, it } from "vitest"
import { CdpClientPool } from "../src/cdp-client-pool.ts"
import { CdpRouter, isRootRoutableBrowserContextMethod } from "../src/cdp-router.ts"
import type { CdpEvent } from "../src/protocol.ts"
import type { ChildTarget, ConnectedTarget } from "../src/relay-types.ts"
import { TargetRegistry } from "../src/target-registry.ts"

function root(options: {
  readonly tabId: number
  readonly sessionId: string
  readonly targetId: string
  readonly browserControlSessionId?: string
  readonly browserContextId?: string
  readonly owner?: "relay" | "user"
  readonly crashed?: boolean
}): ConnectedTarget {
  return {
    tabId: options.tabId,
    sessionId: options.sessionId,
    targetInfo: {
      targetId: options.targetId,
      type: "page",
      title: options.targetId,
      url: `https://example.com/${options.targetId}`,
      attached: true,
      canAccessOpener: false,
      ...(options.browserContextId ? { browserContextId: options.browserContextId } : {}),
    },
    owner: options.owner ?? "relay",
    ...(options.browserControlSessionId ? { browserControlSessionId: options.browserControlSessionId } : {}),
    ...(options.crashed ? { crashed: true } : {}),
  }
}

function setup() {
  const events: { client: object; event: CdpEvent }[] = []
  const clients = new CdpClientPool<object>((client, event) => events.push({ client, event }), () => {})
  const registry = new TargetRegistry()
  const router = new CdpRouter(clients, registry)
  return { clients, registry, router, events }
}

describe("CdpRouter", () => {
  it("does not reinterpret a disconnected client as a raw client", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client)
    registry.addRootTarget(root({ tabId: 1, sessionId: "root", targetId: "target", owner: "user" }))
    expect(router.session(client, "root")).toBeDefined()
    clients.unregister(client)
    expect(router.session(client, "root")).toBeUndefined()
    expect(router.visibleTargetInfos(client)).toEqual([])
  })
  it("classifies browser-context methods that Chrome routes through a root tab", () => {
    for (const method of [
      "Browser.grantPermissions",
      "Browser.resetPermissions",
      "Storage.getCookies",
      "Storage.setCookies",
      "Storage.clearCookies",
    ]) {
      expect(isRootRoutableBrowserContextMethod(method)).toBe(true)
    }
    expect(isRootRoutableBrowserContextMethod("Runtime.evaluate")).toBe(false)
  })

  it("prefers a session-owned root for a named client", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    const owned = root({
      tabId: 1,
      sessionId: "owned-root",
      targetId: "owned-target",
      browserControlSessionId: "session-a",
    })
    registry.addRootTarget(owned)
    registry.addRootTarget(root({
      tabId: 2,
      sessionId: "unrelated-root",
      targetId: "unrelated-target",
      owner: "user",
    }))

    expect(router.preferredRoot(client)).toBe(owned)

    registry.addRootTarget(root({
      tabId: 3,
      sessionId: "second-owned-root",
      targetId: "second-owned-target",
      browserControlSessionId: "session-a",
    }))
    expect(router.preferredRoot(client)).toBe(owned)
  })

  it("recognizes browser session aliases", () => {
    const { clients, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    const browserAlias = clients.createBrowserAlias(client)

    expect(router.isBrowserAlias(client, browserAlias)).toBe(true)
    expect(router.isBrowserAlias(client, "unknown-session")).toBe(false)
  })

  it("skips a crashed owned root that precedes a healthy sibling", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    registry.addRootTarget(root({ tabId: 1, sessionId: "crashed-root", targetId: "crashed-target", browserControlSessionId: "session-a" }))
    registry.markRootTargetCrashed(1)
    const healthy = root({ tabId: 2, sessionId: "healthy-root", targetId: "healthy-target", browserControlSessionId: "session-a" })
    registry.addRootTarget(healthy)

    expect(registry.listRootTargets().map((target) => target.tabId)).toEqual([1, 2])
    expect(router.preferredRoot(client)).toBe(healthy)
    expect(router.visibleRoots(client)).toHaveLength(2)
    expect(router.session(client, "crashed-root")).toEqual({ tabId: 1, rootSessionId: "crashed-root" })
  })

  it("does not replace crashed owned roots with an unrelated healthy root", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    for (const tabId of [1, 2]) {
      registry.addRootTarget(root({ tabId, sessionId: `root-${tabId}`, targetId: `target-${tabId}`, browserControlSessionId: "session-a" }))
      registry.markRootTargetCrashed(tabId)
    }
    registry.addRootTarget(root({ tabId: 3, sessionId: "unrelated-root", targetId: "unrelated-target", owner: "user" }))

    expect(router.preferredRoot(client)).toBeUndefined()
  })

  it("does not fall through from an empty named session to an unrelated root", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    registry.addRootTarget(root({
      tabId: 1,
      sessionId: "unrelated-root",
      targetId: "unrelated-target",
    }))

    expect(router.visibleRoots(client)).toHaveLength(1)
    expect(router.preferredRoot(client)).toBeUndefined()
  })

  it("groups raw roots in the default browser context", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client)
    const visible = root({ tabId: 1, sessionId: "root-1", targetId: "target-1" })
    registry.addRootTarget(visible)

    expect(router.preferredRoot(client)).toBe(visible)

    registry.addRootTarget(root({ tabId: 2, sessionId: "root-2", targetId: "target-2" }))
    expect(router.preferredRoot(client)).toBe(visible)
  })

  it("groups multiple raw roots only when they prove the same browser context", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client)
    const first = root({ tabId: 1, sessionId: "root-1", targetId: "target-1", browserContextId: "context-a" })
    registry.addRootTarget(first)
    registry.addRootTarget(root({ tabId: 2, sessionId: "root-2", targetId: "target-2", browserContextId: "context-a" }))
    expect(router.preferredRoot(client)).toBe(first)

    registry.addRootTarget(root({ tabId: 3, sessionId: "root-3", targetId: "target-3", browserContextId: "context-b" }))
    expect(router.preferredRoot(client)).toBeUndefined()
    expect(router.preferredRoot(client, "context-a")).toBe(first)
    expect(router.preferredRoot(client, "missing-context")).toBeUndefined()
  })

  it("validates context identity and skips crashed roots for named clients", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    registry.addRootTarget(root({
      tabId: 1,
      sessionId: "crashed-root",
      targetId: "crashed-target",
      browserControlSessionId: "session-a",
      browserContextId: "context-a",
      crashed: true,
    }))
    const healthy = root({
      tabId: 2,
      sessionId: "healthy-root",
      targetId: "healthy-target",
      browserControlSessionId: "session-a",
      browserContextId: "context-a",
    })
    registry.addRootTarget(healthy)
    registry.addRootTarget(root({
      tabId: 3,
      sessionId: "other-context-root",
      targetId: "other-context-target",
      browserControlSessionId: "session-a",
      browserContextId: "context-b",
    }))

    expect(router.preferredRoot(client)).toBe(healthy)
    expect(router.preferredRoot(client, "context-a")).toBe(healthy)
    expect(router.preferredRoot(client, "context-b")?.tabId).toBe(3)
    expect(router.preferredRoot(client, "context-missing")).toBeUndefined()
  })

  it("excludes crashed roots from raw context routing while keeping explicit access", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client)
    registry.addRootTarget(root({ tabId: 1, sessionId: "root-1", targetId: "target-1" }))
    const crashed = registry.markRootTargetCrashed(1)
    expect(router.preferredRoot(client)).toBeUndefined()
    expect(router.targetForAttach(client, "target-1")).toBe(crashed)

    const healthy = root({ tabId: 2, sessionId: "root-2", targetId: "target-2" })
    registry.addRootTarget(healthy)
    expect(router.preferredRoot(client)).toBe(healthy)
  })

  it("resolves only targets visible to the client", () => {
    const { clients, registry, router } = setup()
    const owner = {}
    const other = {}
    clients.register(owner, "session-a")
    clients.register(other, "session-b")
    const target = root({
      tabId: 1,
      sessionId: "bc-tab-1",
      targetId: "target-1",
      browserControlSessionId: "session-a",
    })
    registry.addRootTarget(target)

    expect(router.targetForAttach(owner, "target-1")).toBe(target)
    expect(router.targetInfo(owner, { sessionId: "bc-tab-1" })).toBe(target)
    expect(router.targetForAttach(other, "target-1")).toBeUndefined()
    expect(router.targetInfo(other, { targetId: "target-1" })).toBeUndefined()
  })

  it("routes root aliases without a Chrome session and child aliases with one", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client)
    const target = root({ tabId: 1, sessionId: "bc-tab-1", targetId: "target-1" })
    registry.addRootTarget(target)
    const child: ChildTarget = {
      tabId: 1,
      sessionId: "child-session",
      parentSessionId: target.sessionId,
      targetInfo: { ...target.targetInfo, targetId: "child-target", type: "iframe" },
      waitingForDebugger: false,
    }
    registry.addChildTarget(child)
    const rootAlias = clients.createTargetAlias(client, target)
    const childAlias = clients.createTargetAlias(client, child)

    expect(router.session(client, rootAlias)).toEqual({ tabId: 1, rootSessionId: "bc-tab-1" })
    expect(router.session(client, childAlias)).toEqual({
      tabId: 1,
      rootSessionId: "bc-tab-1",
      chromeSessionId: "child-session",
    })
  })

  it("does not resolve identity-free or hidden session routes", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-b")
    registry.addRootTarget(root({
      tabId: 1,
      sessionId: "bc-tab-1",
      targetId: "target-1",
      browserControlSessionId: "session-a",
    }))

    expect(router.targetInfo(client, {})).toBeUndefined()
    expect(router.session(client, "bc-tab-1")).toBeUndefined()
    expect(router.rootForSession(client, "bc-tab-1")).toBeUndefined()
  })

  it("rejects stale aliases and children without a live root", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client)
    const target = root({ tabId: 1, sessionId: "bc-tab-1", targetId: "target-1" })
    registry.addRootTarget(target)
    const alias = clients.createTargetAlias(client, target)

    registry.addRootTarget(root({ tabId: 1, sessionId: "bc-tab-2", targetId: "target-2" }))
    expect(router.session(client, alias)).toBeUndefined()

    registry.detachRootTargetState(1)
    const orphan: ChildTarget = {
      tabId: 1,
      sessionId: "orphan-session",
      parentSessionId: "bc-tab-missing",
      targetInfo: { ...target.targetInfo, targetId: "orphan-target", type: "iframe" },
      waitingForDebugger: false,
    }
    registry.addChildTarget(orphan)
    expect(router.targetForAttach(client, "orphan-target")).toBeUndefined()
    expect(router.session(client, "orphan-session")).toBeUndefined()
  })

  it("does not fall through from an explicit hidden target to a visible session", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    const visible = root({ tabId: 1, sessionId: "visible-session", targetId: "visible-target", browserControlSessionId: "session-a" })
    const hidden = root({ tabId: 2, sessionId: "hidden-session", targetId: "hidden-target", browserControlSessionId: "session-b" })
    registry.addRootTarget(visible)
    registry.addRootTarget(hidden)

    expect(router.targetInfo(client, {
      targetId: "hidden-target",
      sessionId: "visible-session",
    })).toBeUndefined()
  })

  it("prunes aliases when ownership hides a tab even without an announcement", () => {
    const { clients, registry, router, events } = setup()
    const client = {}
    clients.register(client, "session-a")
    const rawTarget = root({ tabId: 1, sessionId: "raw-session", targetId: "raw-target" })
    registry.addRootTarget(rawTarget)
    const alias = clients.createTargetAlias(client, rawTarget)
    const browserAlias = clients.createBrowserAlias(client)
    registry.addRootTarget(root({
      tabId: 2,
      sessionId: "owned-session",
      targetId: "owned-target",
      browserControlSessionId: "session-a",
    }))

    router.reconcileClient(client)

    expect(clients.alias(client, alias)).toBeUndefined()
    expect(router.isBrowserAlias(client, browserAlias)).toBe(true)
    expect(events).toEqual([])
  })

  it("reconciles announcements and aliases across ownership reservation and rollback", () => {
    const { clients, registry, router, events } = setup()
    const owner = { name: "owner" }
    const other = { name: "other" }
    const raw = { name: "raw" }
    clients.register(owner, "session-a")
    clients.register(other, "session-b")
    clients.register(raw)
    const target = root({ tabId: 1, sessionId: "user-root", targetId: "user-target", owner: "user" })
    const child: ChildTarget = {
      tabId: 1,
      sessionId: "user-child",
      parentSessionId: target.sessionId,
      targetInfo: { ...target.targetInfo, targetId: "child-target", type: "iframe" },
      waitingForDebugger: false,
    }
    const rawTarget = root({ tabId: 2, sessionId: "raw-root", targetId: "raw-target" })
    registry.addRootTarget(target)
    registry.addRootTarget(rawTarget)
    registry.addChildTarget(child)
    for (const client of clients) {
      expect(router.canSeeTarget(client, target)).toBe(true)
      clients.announce(client, target)
      clients.announce(client, child)
    }
    const ownerAlias = clients.createTargetAlias(owner, target)
    const otherAlias = clients.createTargetAlias(other, target)
    const otherChildAlias = clients.createTargetAlias(other, child)
    const rawAlias = clients.createTargetAlias(raw, target)
    const aliasOnly = clients.createTargetAlias(owner, rawTarget)
    const browserAlias = clients.createBrowserAlias(other)
    events.length = 0

    const reservation = registry.reserveTargetOwnership(target.targetInfo.targetId, "session-a")
    for (const client of clients) router.reconcileClient(client)

    const detached: CdpEvent[] = [
      {
        sessionId: target.sessionId,
        method: "Target.detachedFromTarget",
        params: { sessionId: child.sessionId, targetId: child.targetInfo.targetId },
      },
      {
        method: "Target.detachedFromTarget",
        params: { sessionId: target.sessionId, targetId: target.targetInfo.targetId },
      },
    ]
    expect(events).toEqual([
      ...detached.map((event) => ({ client: other, event })),
      ...detached.map((event) => ({ client: raw, event })),
    ])
    for (const client of [other, raw]) {
      expect(router.canSeeTab(client, target.tabId)).toBe(false)
      expect(clients.hasSession(client, target.sessionId)).toBe(false)
      expect(clients.hasSession(client, child.sessionId)).toBe(false)
      expect(router.session(client, target.sessionId)).toBeUndefined()
      expect(router.targetForAttach(client, child.targetInfo.targetId)).toBeUndefined()
    }
    expect(clients.alias(other, otherAlias)).toBeUndefined()
    expect(clients.alias(other, otherChildAlias)).toBeUndefined()
    expect(clients.alias(raw, rawAlias)).toBeUndefined()
    expect(clients.alias(owner, aliasOnly)).toBeUndefined()
    expect(router.isBrowserAlias(other, browserAlias)).toBe(true)
    expect(router.session(owner, ownerAlias)).toEqual({ tabId: 1, rootSessionId: target.sessionId })
    expect(clients.hasSession(owner, child.sessionId)).toBe(true)

    events.length = 0
    registry.rollbackTargetOwnership(reservation)
    for (const client of clients) router.reconcileClient(client)
    expect(events).toEqual([])
    for (const client of clients) expect(router.canSeeTab(client, target.tabId)).toBe(true)
    expect(router.canSeeTab(owner, rawTarget.tabId)).toBe(true)
    expect(clients.alias(owner, aliasOnly)).toBeUndefined()

    const event: CdpEvent = { sessionId: child.sessionId, method: "Runtime.executionContextsCleared", params: {} }
    clients.sendToViewers(target.sessionId, event, (client, tabId) => router.canSeeTab(client, tabId))
    expect(events).toEqual([{ client: owner, event }])

    events.length = 0
    for (const client of [other, raw]) {
      clients.announce(client, target)
      clients.announce(client, child)
      expect(clients.hasSession(client, target.sessionId)).toBe(true)
      expect(clients.hasSession(client, child.sessionId)).toBe(true)
    }
    expect(events.map(({ event }) => event.method)).toEqual([
      "Target.attachedToTarget",
      "Target.attachedToTarget",
      "Target.attachedToTarget",
      "Target.attachedToTarget",
    ])
    expect(router.session(other, otherAlias)).toBeUndefined()
    expect(router.session(other, otherChildAlias)).toBeUndefined()
    expect(router.session(raw, rawAlias)).toBeUndefined()
    const newAlias = clients.createTargetAlias(other, child)
    expect(router.session(other, newAlias)).toEqual({ tabId: 1, rootSessionId: target.sessionId, chromeSessionId: child.sessionId })
  })

  it("keeps real session routes alive after a client detaches only its alias", () => {
    const { clients, registry, router, events } = setup()
    const client = {}
    clients.register(client)
    const target = root({ tabId: 1, sessionId: "bc-tab-1", targetId: "target-1" })
    registry.addRootTarget(target)
    clients.announce(client, target)
    const alias = clients.createTargetAlias(client, target)
    events.length = 0

    clients.detach(client, alias)

    expect(router.session(client, alias)).toBeUndefined()
    expect(router.session(client, target.sessionId)).toEqual({ tabId: 1, rootSessionId: target.sessionId })
    expect(registry.getRootTargetByTabId(1)).toBe(target)
    expect(clients.hasSession(client, target.sessionId)).toBe(true)
    expect(events).toEqual([])
  })

  it("lists only visible roots and exposed children", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    const visible = root({ tabId: 1, sessionId: "bc-tab-1", targetId: "target-1", browserControlSessionId: "session-a" })
    const hidden = root({ tabId: 2, sessionId: "bc-tab-2", targetId: "target-2", browserControlSessionId: "session-b" })
    registry.addRootTarget(visible)
    registry.addRootTarget(hidden)
    registry.addChildTarget({
      tabId: 1,
      sessionId: "child-visible",
      parentSessionId: visible.sessionId,
      targetInfo: { ...visible.targetInfo, targetId: "child-visible-target", type: "worker" },
      waitingForDebugger: false,
    })
    registry.addChildTarget({
      tabId: 1,
      sessionId: "child-held",
      parentSessionId: visible.sessionId,
      targetInfo: { ...visible.targetInfo, targetId: "child-held-target", type: "page", url: "" },
      waitingForDebugger: false,
    })

    expect(router.visibleTargetInfos(client).map((target) => target.targetId)).toEqual(["target-1", "child-visible-target"])
  })
})

